// Shared, bounded animation loop: the hidden gradient is exposed in fixed grid cells.
(()=>{const make=id=>{const c=document.createElement('canvas');c.id=id;c.setAttribute('aria-hidden','true');document.body.append(c);return c},reveal=make('uncover-art'),art=make('concept-art'),rc=reveal.getContext('2d'),ac=art.getContext('2d'),field=document.createElement('canvas'),fc=field.getContext('2d');field.width=320;field.height=240;
const cells=new Map(),random=(a,b)=>a+Math.random()*(b-a),palette=['#ffd77d','#ff8d99','#f45282','#f6ae56','#a9dbcd','#c2c5ed','#fff1c0'];let w=innerWidth,h=innerHeight,step=15,mode='',branches=[],flowers=[],blocks=new Map(),frontier=[],last=0,textureAt=0,blockAt=0,raf=0,visible=true;const seed=random(0,100);
function resize(){w=innerWidth;h=innerHeight;step=Number(getComputedStyle(document.documentElement).getPropertyValue('--site-gridSpacing'))||15;for(const c of [reveal,art]){c.width=w;c.height=h}cells.clear();if(mode){const previous=mode;mode='';start(previous)}}
function gradient(now){fc.fillStyle='#fff0cd';fc.fillRect(0,0,320,240);for(let i=0;i<9;i++){const x=160+Math.sin(seed+i*2.1+now*.00011)*170,y=120+Math.cos(i*1.7+now*.00009)*130,g=fc.createRadialGradient(x,y,0,x,y,130);g.addColorStop(0,palette[i%palette.length]);g.addColorStop(1,palette[i%palette.length]+'00');fc.fillStyle=g;fc.fillRect(0,0,320,240)}fc.strokeStyle='#ffffff42';fc.lineWidth=.35;const wide=step*5;fc.beginPath();for(let x=0;x<w;x+=wide){fc.moveTo(x/w*320,0);fc.lineTo(x/w*320,240)}for(let y=0;y<h;y+=wide){fc.moveTo(0,y/h*240);fc.lineTo(320,y/h*240)}fc.stroke();for(let i=0;i<7;i++){fc.beginPath();fc.strokeStyle=palette[(i+3)%palette.length]+'a0';fc.lineWidth=.6;for(let x=-20;x<340;x+=4){const y=120+Math.sin(x*.015+i+now*.0002)*70+Math.cos(x*.023-i)*20;i===0&&x===-20?fc.moveTo(x,y):x===-20?fc.moveTo(x,y):fc.lineTo(x,y)}fc.stroke()}fc.fillStyle='#ffffff25';for(let i=0;i<1300;i++)fc.fillRect(Math.random()*320,Math.random()*240,.45,.45)}
function active(){if(document.hidden||document.querySelector('#customize-panel:not([hidden])'))return false;return !document.getElementById('info-panel').hidden||Number(document.body.dataset.narrativeStage)<5||document.body.dataset.artworkAllowed==='true'}
function pointer(e){if(!active()||document.body.dataset.narrativeBusy==='true'||e.clientY<64)return;const now=performance.now(),radius=9,x0=Math.floor(e.clientX/step),y0=Math.floor(e.clientY/step);for(let y=y0-radius;y<=y0+radius;y++)for(let x=x0-radius;x<=x0+radius;x++){const distance=Math.hypot(x-x0,y-y0);if(distance>radius)continue;const key=x+','+y;cells.set(key,{x:x*step,y:y*step,born:now,strength:Math.pow(1-distance/radius,.65)})}if(cells.size>3000)for(const key of [...cells.keys()].slice(0,cells.size-3000))cells.delete(key);schedule()}
function start(value){mode=mode===value?'':value;branches=[];flowers=[];blocks.clear();frontier=[];ac.clearRect(0,0,w,h);if(mode==='organic'){for(let i=0;i<28;i++)branches.push({x:random(0,w),y:random(70,h),a:random(0,Math.PI*2),life:random(160,420),hue:Math.floor(random(0,7)),phase:random(0,10)});for(let i=0;i<16;i++)flowers.push({x:random(20,w-20),y:random(85,h-20),r:random(25,85),petals:Math.floor(random(5,11)),phase:random(0,6),age:0})}if(mode==='power')frontier.push([Math.floor(random(0,w/(step*4))),Math.floor(random(1,h/(step*4)))]);art.dataset.mode=mode;schedule()}
function organic(now,dt){ac.save();ac.globalCompositeOperation='destination-out';ac.fillStyle='rgba(0,0,0,.0005)';ac.fillRect(0,64,w,h-64);ac.restore();for(const p of branches){if(p.life<=0)continue;const ox=p.x,oy=p.y;p.a+=Math.sin(p.phase+now*.0007+p.x*.005)*.06+random(-.07,.07);p.x+=Math.cos(p.a)*dt*.045;p.y+=Math.sin(p.a)*dt*.045;p.life-=dt*.025;ac.strokeStyle=palette[p.hue];ac.lineWidth=1.1;ac.beginPath();ac.moveTo(ox,oy);ac.lineTo(p.x,p.y);ac.stroke();if(p.x<0||p.x>w||p.y<64||p.y>h)p.a+=Math.PI}for(const f of flowers){f.age+=dt*.00013;if(f.age>1)continue;const angle=f.age*Math.PI*2*2,r=f.r*Math.sin(f.petals*angle+f.phase)*f.age,x=Math.round((f.x+Math.cos(angle)*r)/step)*step,y=Math.round((f.y+Math.sin(angle)*r)/step)*step;ac.globalAlpha=.65;ac.fillStyle=palette[Math.floor(f.petals)%7];ac.fillRect(x,y,step*.7,step*.7);ac.globalAlpha=1}if(branches.every(p=>p.life<=0)){for(const p of branches){p.life=random(200,400);p.a=random(0,7)}}}
function structure(now){if(now-blockAt<130)return;blockAt=now;const size=step*4,cols=Math.ceil(w/size),rows=Math.ceil(h/size);for(let n=0;n<2&&frontier.length;n++){const i=Math.floor(Math.random()*Math.min(frontier.length,24)),[x,y]=frontier.splice(i,1)[0],key=x+','+y;if(x<0||x>=cols||y<1||y>=rows||blocks.has(key))continue;blocks.set(key,now);ac.fillStyle=Math.random()>.25?'#101c54eb':'#004bffdc';ac.fillRect(x*size,y*size,size,size);ac.strokeStyle='#b8c8ff70';ac.strokeRect(x*size+.5,y*size+.5,size-1,size-1);for(const [dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]])frontier.push([x+dx,y+dy]);if(frontier.length>5000)frontier.splice(0,2000)}}
function draw(now){raf=0;const dt=Math.min(40,now-last||16);last=now;rc.clearRect(0,0,w,h);if(mode&&(document.getElementById('home-panel').hidden||Number(document.body.dataset.narrativeStage)!==4)){mode='';art.dataset.mode='';ac.clearRect(0,0,w,h)}if(!active()){cells.clear();if(mode){mode='';art.dataset.mode='';ac.clearRect(0,0,w,h)}return}if(now-textureAt>100){gradient(now);textureAt=now}for(const [key,c]of cells){const age=(now-c.born)/1700;if(age>=1){cells.delete(key);continue}rc.globalAlpha=c.strength*Math.pow(1-age,1.5);rc.drawImage(field,Math.max(0,c.x)/w*320,Math.max(0,c.y)/h*240,step/w*320,step/h*240,c.x,c.y,step+.2,step+.2)}rc.globalAlpha=1;ac.save();ac.beginPath();ac.rect(3,64,w-6,h-67);ac.clip();if(mode==='organic')organic(now,dt);if(mode==='power')structure(now);ac.restore();if(cells.size||mode==='organic'||mode==='power'&&frontier.length)raf=requestAnimationFrame(draw)}
function schedule(){if(!raf)raf=requestAnimationFrame(draw)}
const tokens=[...document.querySelectorAll('.quote-word')];for(const [index,label,value]of[[4,'Generate flowing patterns','organic'],[5,'Generate flowing patterns','organic'],[10,'Generate growing structures','power']]){const token=tokens[index];if(!token)continue;token.removeAttribute('aria-hidden');token.setAttribute('role','button');token.tabIndex=0;token.setAttribute('aria-label',label);function trigger(){if(active()&&!document.getElementById('home-panel').hidden&&Number(document.body.dataset.narrativeStage)===4&&document.body.dataset.narrativeBusy==='false')start(value)}token.addEventListener('click',trigger);token.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopPropagation();trigger()}})}
addEventListener('pointermove',pointer,{passive:true});addEventListener('message',e=>{const f=document.querySelector('#artwork-host iframe');if(e.origin!==location.origin||e.source!==f?.contentWindow||e.data?.type!=='reveal-pointer')return;const r=f.getBoundingClientRect();pointer({clientX:r.left+e.data.x,clientY:r.top+e.data.y})});addEventListener('resize',resize);document.addEventListener('site-style-change',()=>{const next=Number(getComputedStyle(document.documentElement).getPropertyValue('--site-gridSpacing'))||15;if(next!==step)resize()});document.addEventListener('narrative-stage-change',schedule);new MutationObserver(schedule).observe(document.getElementById('home-panel'),{attributes:true,attributeFilter:['hidden']});document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(raf);raf=0}else schedule()});resize();})();
